INSERT INTO `blog_posts` VALUES ('6657f0ae-f662-4c57-8152-1e5d385846fd','schengen-visa-checklist-2026','Schengen Visa Checklist for Indian Travellers (2026)','Documents, timelines and common mistakes to avoid when applying for your first Europe trip.','Visa Tips','[\"Start with a valid passport, travel insurance and confirmed itinerary.\", \"Financial proof should show sufficient balance for the trip.\", \"Book your VFS appointment early — peak summer slots fill quickly.\"]','/images/hero/holiday-packages-hero-desktop.webp','[]',7,1,'2026-04-28 00:00:00.000',NULL,NULL,'2026-06-26 21:32:25.493','2026-06-26 21:32:25.493'),('8fb99873-5194-4706-9b5e-fafc0ce7010e','goa-monsoon-getaway-guide','Goa Beyond the Beaches: A Monsoon Getaway Guide','Quiet lanes, lush greenery and off-season deals make monsoon Goa a hidden gem for slow travellers.','Domestic Travel','[\"Monsoon transforms Goa into a greener, calmer version of itself.\", \"Plan inland experiences like Dudhsagar falls and Fontainhas walks.\", \"Pack light rain gear — our team can help swap outdoor plans if showers roll in.\"]','/images/hero/holiday-packages-hero-desktop.webp','[]',5,1,'2026-05-12 00:00:00.000',NULL,NULL,'2026-06-26 21:32:25.493','2026-06-26 21:32:25.493'),('fe01cab2-f8eb-47ba-8704-d71b5c8684a2','kerala-houseboat-planning-tips','Planning the Perfect Kerala Houseboat Experience','Alleppey backwaters done right — cabin types, meal plans and the best season to cruise.','Holiday Ideas','[\"Choose between deluxe and premium houseboats based on AC hours.\", \"October to February offers pleasant weather.\", \"Combine Alleppey with Munnar or Thekkady for a classic Kerala circuit.\"]','/images/hero/holiday-packages-hero-desktop.webp','[]',4,1,'2026-03-15 00:00:00.000',NULL,NULL,'2026-06-26 21:32:25.493','2026-06-26 21:32:25.493');
