INSERT INTO `destinations` VALUES ('0af88be4-5452-4957-be01-db871f8c5a52','kerala','domestic','Kerala','South India','/images/homepage/hero/1784903877682-chatgpt-image-jul-24-2026-08-07-42-pm.png','Backwaters, houseboats and lush hill stations of God\'s Own Country.','[\"Alleppey houseboat\", \"Munnar tea gardens\", \"Kovalam beach\", \"Ayurveda spa\"]',1,3,'2026-06-27 20:50:02.510','2026-07-26 17:59:33.015'),('2714ca7c-4590-49d9-b084-d43c1f5bf912','northeast','domestic','North East India','North East India','/images/destinations/1785232894003-chatgpt-image-jul-28-2026-03-31-20-pm.png','Living root bridges, monasteries and emerald hills of the seven sisters.','[\"Tawang Monastery\", \"Cherrapunji falls\", \"Kaziranga safari\", \"Majuli island\"]',1,22,'2026-06-27 20:50:02.510','2026-07-28 10:01:36.137'),('29a301b2-6e28-43a8-b519-3f41d698e49c','rajasthan','domestic','Rajasthan','West India','/images/packages/1785087042683-chatgpt-image-jul-26-2026-11-00-25-pm.png','Forts, palaces and golden deserts of the royal land.','[\"Udaipur lake palaces\", \"Jaisalmer desert camp\", \"Jaipur Amber Fort\", \"Jodhpur blue city\"]',1,4,'2026-06-27 20:50:02.510','2026-07-26 17:59:33.047'),('29c1c52f-ac68-43af-9267-56503ca3415e','arunachal-pradesh','domestic','Arunachal Pradesh','North East India','/images/packages/1785085391884-chatgpt-image-jul-26-2026-10-32-54-pm.png',NULL,'[]',1,17,'2026-07-26 10:58:42.628','2026-07-26 17:59:33.491'),('30280508-04b0-43e1-abfc-e8704a5c6f56','lakshadweep','domestic','Lakshadweep','Island','/images/packages/1785078864041-chatgpt-image-jul-26-2026-08-44-09-pm.png','Discover Lakshadweep, India\'s hidden tropical paradise, where turquoise lagoons, coral reefs, untouched islands and serene beaches offer an unforgettable island escape.','[\"Agatti Island\", \"Bangaram Island Scuba Diving &amp; Snorkeling Glass Bottom Boat Ride Sunset at Kadma\"]',1,21,'2026-07-02 06:13:12.850','2026-07-26 17:59:33.709'),('36366e07-018a-46a2-b392-15df4779463e','thailand','international','Thailand','South-East Asia','/images/hero/holiday-packages-hero-desktop.webp','Phuket beaches, Bangkok nightlife and Krabi\'s emerald waters.','[\"Phi Phi islands\", \"Bangkok temples\", \"Krabi\", \"Pattaya\"]',0,3,'2026-06-27 20:50:02.510','2026-07-05 07:46:19.712'),('5084c596-ff35-4305-ad23-ed16dcd60877','uttarpradesh','domestic','Uttarpradesh','North India','/images/destinations/1785231734478-chatgpt-image-jul-28-2026-03-11-50-pm.png','Discover Uttar Pradesh, the heart of India\'s spiritual heritage, where sacred temples, ancient cities, Mughal monuments, wildlife and vibrant culture create unforgettable travel experiences.','[\"Kashi Vishwanath Temple\", \"Shri Ram Janmabhoomi, Ayodhya\", \"Taj Mahal, Agra\", \"Triveni Sangam, Prayagraj\", \"Dudhwa National Park\", \"Mathura &amp; Vrindavan\"]',1,20,'2026-07-26 17:51:49.192','2026-07-28 09:42:17.010'),('5720a30d-5966-428c-aedf-c083e8b30c66','west-bengal','domestic','West Bengal','East India','/images/packages/1785228437477-chatgpt-image-jul-28-2026-02-17-05-pm.png','Experience the cultural soul of West Bengal with colonial heritage, Himalayan hill stations, tea gardens, wildlife sanctuaries, pristine beaches and spiritual destinations.','[\"Darjeeling &amp; Tiger Hill\", \"Victoria Memorial &amp; Howrah Bridge\", \"Sundarbans Mangrove Safari Dooars Tea Gardens &amp; Rhino Safari\", \"Digha &amp; Mandarmani Beaches\"]',1,18,'2026-07-02 06:13:12.850','2026-07-28 08:52:20.375'),('62338f26-c227-4cbd-99c6-68b886c524e6','odisha','domestic','Odisha','East India','/images/packages/1785086029511-chatgpt-image-jul-26-2026-10-43-35-pm.png','Discover the timeless charm of East India with Odisha\'s sacred temples, pristine beaches and rich heritage, combined with West Bengal\'s colonial grandeur, Himalayan hill stations, tea gardens and vibrant culture.','[\"Jagannath Temple, Puri\", \"Konark Sun Temple\", \"Victoria Memorial, Kolkata Howrah Bridge\", \"Darjeeling &amp; Tiger Hill Sunrise\"]',1,19,'2026-07-02 06:13:12.850','2026-07-26 17:59:33.598'),('7b9d8fc9-6be9-493a-be0c-af1f046c3b11','ladakh','domestic','Ladakh','North India','/images/destinations/1785234006605-chatgpt-image-jul-28-2026-03-49-55-pm.png','High-altitude desert, monasteries and Pangong\'s blue magic.','[\"Pangong Tso\", \"Nubra Valley\", \"Magnetic Hill\", \"Hemis Monastery\"]',1,7,'2026-06-27 20:50:02.510','2026-07-28 10:20:09.360'),('8883cfeb-02f4-4283-ac0b-e0b56499ac5a','gujarat','domestic','Gujarat','West India','/images/destinations/1785233615247-chatgpt-image-jul-28-2026-03-43-21-pm.png','Experience Gujarat — a land of sacred temples, majestic wildlife, white deserts, serene beaches, vibrant culture, and iconic modern attractions.','[\"Dwarkadhish Temple\", \"Somnath Jyotirlinga\", \"Gir Lion Safari\", \"White Rann of Kutch\", \"Statue of Unity\", \"Saputara Hill Station\"]',1,15,'2026-07-02 06:13:12.850','2026-08-02 09:13:36.090'),('8cecfa77-b648-428f-8c85-0f8ad72e799b','andaman','domestic','Andaman Islands','Island','/images/packages/1785071672727-chatgpt-image-jul-26-2026-06-44-21-pm.png','Turquoise reefs, white sand and untouched islands.','[\"Radhanagar Beach\", \"Scuba at Havelock\", \"Cellular Jail\", \"Neil Island\"]',1,10,'2026-06-27 20:50:02.510','2026-07-26 17:59:33.251'),('a37705dc-3e34-40bb-8320-23df955244ff','karnataka','domestic','Karnataka','South India','/images/destinations/1785234089018-chatgpt-image-jul-28-2026-03-51-14-pm.png','Discover Karnataka, a perfect blend of royal heritage, lush coffee plantations, scenic hill stations, pristine beaches, ancient temples and thrilling wildlife experiences.','[\"Mysore Palace\", \"Coorg Coffee Plantations Hampi UNESCO Heritage Kabini Wildlife Safari\", \"Chikmagalur Hills\", \"Gokarna &amp; Murudeshwar BeachesExplore Our Karnataka Tour\"]',1,12,'2026-07-02 06:13:12.850','2026-07-28 10:21:30.731'),('a56cbb71-b15d-4b09-8462-49fa241d7f5e','dubai','international','Dubai','Middle East','/images/hero/holiday-packages-hero-desktop.webp','Skyscrapers, deserts and luxury shopping in the city of gold.','[\"Burj Khalifa\", \"Desert safari\", \"Dubai Marina cruise\", \"Atlantis Aquaventure\"]',0,1,'2026-06-27 20:50:02.510','2026-07-05 07:46:03.643'),('ae04de40-1db0-406b-8f9e-91566a494df2','maldives','international','Maldives','Indian Ocean','/images/hero/holiday-packages-hero-desktop.webp','Overwater villas in the world\'s most photographed lagoons.','[\"Water villa stay\", \"Snorkeling reefs\", \"Sunset cruise\", \"Private sandbank\"]',0,4,'2026-06-27 20:50:02.510','2026-07-05 07:46:29.058'),('b31f151d-018e-45f2-b989-b77235d03879','kashmir','domestic','Jammu and Kashmir','North India','/images/destinations/1785076174298-chatgpt-image-jul-26-2026-07-58-56-pm.png','Paradise on earth — snow peaks, shikaras and meadows.','[\"Dal Lake shikara\", \"Gulmarg gondola\", \"Pahalgam valley\", \"Sonmarg glacier\"]',1,1,'2026-06-27 20:50:02.510','2026-07-26 17:59:32.921'),('bb8484f9-0d2d-4b49-bcd5-80cab8dd514f','sikkim','domestic','Sikkim','North East India','/images/destinations/1785084021382-chatgpt-image-jul-26-2026-10-10-05-pm.png',NULL,'[]',1,8,'2026-07-26 07:30:15.349','2026-07-26 17:59:33.186'),('bdf2febb-5047-4c3e-a04d-173d3ca9efad','tamil-nadu','domestic','Tamil Nadu','South India','/images/destinations/1785233303513-chatgpt-image-jul-28-2026-03-38-09-pm.png','Dravidian temples, French heritage and Nilgiri tea estates.','[\"Ooty hill station\", \"Pondicherry beach\", \"Madurai temple\", \"Rameshwaram\"]',1,11,'2026-06-27 20:50:02.510','2026-07-28 10:08:26.248'),('ce71513d-7577-447c-be30-5740f57c0187','maharashtra','domestic','Maharashtra','West India','/images/packages/1785080262838-chatgpt-image-jul-26-2026-09-07-30-pm.png','Experience the vibrant charm of Maharashtra, where bustling cities, scenic hill stations, sacred temples, pristine beaches and thrilling wildlife create unforgettable journeys.','[\"Marine Drive\", \"Gateway of India Mahabaleshwar Strawberry Farms\", \"Shirdi Sai Baba Temple\", \"Tadoba