INSERT INTO `faqs` VALUES ('09d569e6-bc08-4310-9930-a685f5bb0932','What payment methods do you accept?','We accept bank transfer, UPI and major cards for confirmed bookings.','general',4,1,'2026-06-26 21:32:25.493'),('28da3be8-569d-45fc-992c-ded028422ec5','How quickly will you respond to my inquiry?','WhatsApp inquiries are answered within minutes during business hours.','general',7,1,'2026-06-26 21:32:25.493'),('53a5c18c-f6d9-4337-b2c6-86a2966d5a1b','Can I customise an itinerary?','Every trip we plan is fully customisable — dates, hotels, transfers and sightseeing can be tailored to your budget.','general',3,1,'2026-06-26 21:32:25.493'),('7431cb4e-4113-4549-b297-58d2e73a06a9','What is your cancellation policy?','Cancellation terms depend on airlines, hotels and package partners. We share clear policies before you confirm.','general',8,1,'2026-06-26 21:32:25.493'),('b25cccd1-e4cb-40c5-b327-2121f2b641c4','Do you offer corporate travel management?','Yes. We manage business travel, MICE events, GST invoicing and dedicated account support.','general',6,1,'2026-06-26 21:32:25.493'),('b821adec-b3ff-45de-8f47-eee43070dd71','Do you provide visa assistance?','Yes. We handle documentation checklists, application review, appointment booking and status tracking for 100+ countries.','general',2,1,'2026-06-26 21:32:25.493'),('dfddc41c-ff8a-4922-8f92-59c7443a1916','How do I book a holiday package with YatraNexus?','Browse packages online, fill the inquiry form, or message us on WhatsApp. A travel expert will call you with a customised quote within a few hours.','general',1,1,'2026-06-26 21:32:25.493'),('fe700a00-19c4-4bec-8c0b-f6e1bcb164a0','Is travel insurance included?','Insurance can be added to any package or booked separately.','general',5,1,'2026-06-26 21:32:25.493');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

