INSERT INTO `homepage_settings` VALUES (1,'[{\"tag\": \"Snow &amp; Shikaras\", \"name\": \"Kashmir Valley\", \"slug\": \"kashmir\", \"image\": \"/images/homepage/hero/1784902536646-chatgpt-image-jul-24-2026-07-45-07-pm.png\"}, {\"tag\": \"Royal Heritage\", \"name\": \"Rajasthan\", \"slug\": \"rajasthan\", \"image\": \"/images/homepage/hero/1784903752562-chatgpt-image-jul-24-2026-08-05-36-pm.png\"}, {\"tag\": \"Houseboats\", \"name\": \"Kerala Backwaters\", \"slug\": \"kerala\", \"image\": \"/images/homepage/hero/1784903877682-chatgpt-image-jul-24-2026-08-07-42-pm.png\"}, {\"tag\": \"High Himalaya\", \"name\": \"Ladakh\", \"slug\": \"ladakh\", \"image\": \"/images/homepage/hero/1784902412987-chatgpt-image-jul-24-2026-07-43-20-pm.png\"}, {\"tag\": \"Coral Paradise\", \"name\": \"Lakshadweep\", \"slug\": \"lakshadweep\", \"image\": \"/images/homepage/hero/1784903457399-chatgpt-image-jul-24-2026-08-00-47-pm.png\"}, {\"tag\": \"Mountain Retreat\", \"name\": \"Himachal Pradesh\", \"slug\": \"himachal\", \"image\": \"/images/homepage/hero/1784903133700-chatgpt-image-jul-24-2026-07-55-24-pm.png\"}]',2000,'[\"cabs\", \"flights\", \"hotels\", \"packages\", \"visa\", \"insurance\", \"forex\"]','[\"rajasthan-royal-trail-6d5n\", \"dubai-city-desert-5d4n\", \"bali-island-escape-6d5n\", \"Kerala-Backwater-Honeymoon\", \"kerala-backwater-honeymoon-5d4n\", \"kashmir-kashmir-family-tour-package-5d4n\", \"himachal-spiti-valley-circuit-tour-9d8n\", \"andaman-andaman-honeymoon-special-5d4n\", \"lakshadweep-lakshadweep-adventure-scuba-tour-6d5n\"]','[\"goa\", \"rajasthan\", \"kashmir\", \"himachal\", \"uttarakhand\", \"ladakh\", \"andaman\", \"kerala\"]','Your Journey, Our Priority','Flights, hotels, holidays, cab, visa, insurance, &amp; forex — handled by real travel experts on WhatsApp.','[{\"icon\": \"Headphones\", \"title\": \"24×7 trip support\", \"detail\": \"Real humans on WhatsApp &amp; call — before, during and after your journey.\"}, {\"icon\": \"BadgeCheck\", \"title\": \"Hand-picked partners\", \"detail\": \"Vetted hotels, drivers and local guides — no surprises on the ground.\"}, {\"icon\": \"Wallet\", \"title\": \"Best-price promise\", \"detail\": \"Transparent pricing with the best fares on flights, hotels and packages.\"}, {\"icon\": \"ShieldCheck\", \"title\": \"Safe &amp; secure booking\", \"detail\": \"End-to-end encrypted payments and licensed travel partner you can trust.\"}, {\"icon\": \"Sparkles\", \"title\": \"Fully customisable\", \"detail\": \"Every itinerary is tailored to your dates, budget and travel style.\"}, {\"icon\": \"Globe2\", \"title\": \"100+ destinations\", \"detail\": \"Domestic and international expertise across India, Asia, Europe &amp; beyond.\"}]','[{\"label\": \"Destinations\", \"value\": \"150+\"}, {\"label\": \"Hotels Globally\", \"value\": \"5000+\"}, {\"label\": \"Packages\", \"value\": \"200+\"}, {\"label\": \"Support\", \"value\": \"24×7\"}]','[{\"n\": 1, \"title\": \"Share your holiday need\", \"detail\": \"Tell us where you want to go, your dates and budget — via form or WhatsApp.\"}, {\"n\": 2, \"title\": \"Get in touch with our expert\", \"detail\": \"A dedicated travel expert calls you back with options curated just for you.\"}, {\"n\": 3, \"title\": \"Customise &amp; book\", \"detail\": \"Tweak the itinerary, confirm, pay securely and pack your bags — we handle the rest.\"}]','[{\"icon\": \"Briefcase\", \"title\": \"Business Travel\", \"detail\": \"Domestic flights, hotels and ground transport — managed under one desk.\"}, {\"icon\": \"Users\", \"title\": \"MICE &amp; Group Tours\", \"detail\": \"Meetings, incentives, conferences and exhibitions for teams of 10 to 1000+.\"}, {\"icon\": \"Plane\", \"title\": \"Crew &amp; Bulk Bookings\", \"detail\": \"Negotiated corporate fares, GSA tie-ups and dedicated relationship manager.\"}, {\"icon\": \"FileText\", \"title\": \"GST Invoicing\", \"detail\": \"Compliant GST invoices, monthly reports and centralised billing for your finance team.\"}, {\"icon\": \"Stamp\", \"title\": \"Visa &amp; Forex Desk\", \"detail\": \"Employee visa processing, travel insurance and multi-currency forex cards.\"}, {\"icon\": \"Headphones\", \"title\": \"Dedicated Account Manager\", \"detail\": \"A single point of contact reachable 24×7 for emergency re-routes and changes.\"}]','[{\"name\": \"Adventure\", \"slug\": \"adventure\", \"image\": \"/images/homepage/tour-types/1784901599136-home-page-adventure.png\"}, {\"name\": \"Family\", \"slug\": \"family\", \"image\": \"/images/homepage/tour-types/1784901621195-home-page-family.png\"}, {\"name\": \"Honeymoon\", \"slug\": \"honeymoon\", \"image\": \"/images/homepage/tour-types/1784901628750-home-page-honeymoon.png\"}, {\"name\": \"Leisure\", \"slug\": \"leisure\", \"image\": \"/images/homepage/tour-types/1784901637351-home-page-leisure.png\"}, {\"name\": \"Pilgrimage\", \"slug\": \"pilgrimage\", \"image\": \"/images/homepage/tour-types/1784901862534-chatgpt-image-jul-24-2026-07-34-08-pm.png\"}, {\"name\": \"Solo\", \"slug\": \"solo\", \"image\": \"/images/homepage/hero/1784902068215-chatgpt-image-jul-24-2026-07-36-30-pm.png\"}]','[\"Beaches\", \"Festival\", \"Historical\", \"Luxury\", \"Mountain\", \"Nightlife\", \"Snow\", \"Waterfalls\", \"Wildlife\"]','Ready to plan your next trip?','Share your dates and budget — our expert will call you back the same day.','2026-08-06 14:47:10.215');
