INSERT INTO `packages` VALUES ('0159a73a-6917-4834-ac3c-188d3c10a0db','tamil-nadu-chennai-kanchipuram-mahabalipuram-heritage-tour-4d3n','Chennai – Kanchipuram – Mahabalipuram Heritage Tour','Tamil Nadu','domestic',3,4,'₹ 13,999',NULL,NULL,'/images/packages/1783014612498-chennai-kanchipuram-mahabalipuram-heritage-tour.png','[]','[\"Kapaleeshwarar Temple\", \"Kanchipuram Temples\", \"Shore Temple\", \"Five Rathas\", \"Arjuna\'s Penance\", \"Marina Beach\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Chennai\", \"detail\": \"Arrive in Chennai and visit Marina Beach, Kapaleeshwarar Temple and Fort St. George.\"}, {\"day\": 2, \"title\": \"Kanchipuram Excursion\", \"detail\": \"Explore Ekambareswarar Temple, Kailasanathar Temple and local silk weaving centres.\"}, {\"day\": 3, \"title\": \"Mahabalipuram Sightseeing\", \"detail\": \"Visit Shore Temple, Five Rathas, Arjuna\'s Penance and Krishna\'s Butter Ball.\"}, {\"day\": 4, \"title\": \"Departure\", \"detail\": \"After breakfast, enjoy local shopping before your onward journey.\"}]',1,0,NULL,'Step into the cultural heart of Tamil Nadu with our Chennai – Kanchipuram – Mahabalipuram heritage tour, showcasing timeless temples and architectural brilliance.\n\nExplore Chennai’s landmarks like Marina Beach and Kapaleeshwarar Temple, visit the sacred temples and silk heritage of Kanchipuram, and admire the UNESCO monuments of Mahabalipuram including Shore Temple and Arjuna’s Penance.\n\nWitness intricate carvings, ancient Dravidian architecture, and vibrant traditions that reflect the rich history of South India.\n\nIdeal for history lovers and cultural explorers, this package offers a well-planned itinerary with comfortable stays and seamless travel arrangements.',203,'2026-07-02 04:57:50.606','2026-07-25 11:38:25.435'),('09b57978-8535-42c6-a49c-29497bf06015','goa-romantic-goa-honeymoon-package-5d4n','Romantic Goa Honeymoon Package','Goa','domestic',4,5,'₹ 22,999',NULL,NULL,'/images/packages/1785072392123-chatgpt-image-jul-26-2026-06-56-20-pm.png','[]','[\"Romantic Beach Stay\", \"Sunset Cruise\", \"Candle Light Dinner\", \"Butterfly Beach\", \"Dona Paula View Point\", \"Private Beach Experience\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Goa\", \"detail\": \"Arrive in Goa, check in to your beach resort and enjoy a romantic evening by the sea.\"}, {\"day\": 2, \"title\": \"North Goa Sightseeing\", \"detail\": \"Visit Fort Aguada, Calangute Beach, Baga Beach and Chapora Fort.\"}, {\"day\": 3, \"title\": \"South Goa Exploration\", \"detail\": \"Explore Basilica of Bom Jesus, Dona Paula, Palolem Beach and Butterfly Beach.\"}, {\"day\": 4, \"title\": \"Leisure &amp; Romantic Activities\", \"detail\": \"Enjoy a sunset cruise, candle light dinner and free time at the beach.\"}, {\"day\": 5, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey.\"}]',1,0,NULL,'Celebrate the beginning of your new journey together with our Romantic Goa Honeymoon Package, thoughtfully crafted to create unforgettable moments amidst Goa\'s beautiful beaches, stunning sunsets, and luxurious coastal experiences.\n\nRelax at elegant beach resorts, stroll hand-in-hand along picturesque shorelines, and explore iconic attractions including Butterfly Beach, Dona Paula View Point, Fort Aguada, and Palolem Beach. Make your honeymoon even more memorable with a romantic sunset cruise, beautifully arranged candlelight dinner, and special honeymoon surprises designed exclusively for couples.\n\nPerfect for newlyweds seeking romance, comfort, and privacy, this package combines luxury accommodation, curated sightseeing, private transportation, and intimate experiences to create memories that last a lifetime.',1403,'2026-07-02 04:57:50.606','2026-07-26 13:27:35.632'),('0abb4a64-fe4d-4255-8b90-199dac3544a1','goa-luxury-goa-beach-resort-escape-premium-package-6d5n','Luxury Goa Beach & Resort Escape','Goa','domestic',5,6,'₹ 34,999',NULL,NULL,'/images/packages/1785072643395-chatgpt-image-jul-26-2026-07-00-31-pm.png','[]','[\"Luxury Beach Resort Stay\", \"North &amp; South Goa Sightseeing\", \"Sunset Cruise\", \"Premium Beach Experience\", \"Fine Dining\", \"Spa &amp; Leisure Time\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Goa\", \"detail\": \"Arrive in Goa and relax at your luxury beach resort.\"}, {\"day\": 2, \"title\": \"North Goa Sightseeing\", \"detail\": \"Visit Fort Aguada, Baga Beach, Calangute Beach and Chapora Fort.\"}, {\"day\": 3, \"title\": \"South Goa Sightseeing\", \"detail\": \"Explore Basilica of Bom Jesus, Se Cathedral, Palolem Beach and Butterfly Beach.\"}, {\"day\": 4, \"title\": \"Luxury Leisure Day\", \"detail\": \"Enjoy spa therapies, beach relaxation and resort activities.\"}, {\"day\": 5, \"title\": \"Cruise &amp; Shopping\", \"detail\": \"Experience a sunset cruise and explore Panjim Market for shopping.\"}, {\"day\": 6, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey.\"}]',1,0,NULL,'Experience the finest side of Goa with our Luxury Goa Beach & Resort Escape, a premium holiday package designed for travelers who appreciate comfort, elegance, and world-class hospitality.\n\nStay at luxurious beach resorts while exploring the best of North and South Goa, including Fort Aguada, Baga Beach, Palolem Beach, Butterfly Beach, and the Basilica of Bom Jesus. Indulge in relaxing spa sessions, savour exceptional dining experiences, enjoy a picturesque sunset cruise, and spend your days unwinding amidst Goa\'s breathtaking coastline and premium leisure experiences.\n\nIdeal for couples, luxury travelers, and those seeking a sophisticated coastal retreat, this package combines premium accommodation, exclusive experiences, seamless transportation, and personalized service to deliver an unforgettable luxury holiday in Goa.',1405,'2026-07-02 04:57:50.606','2026-07-26 13:30:50.621'),('0d3bf3c1-266c-4069-8400-6fea8b873b69','kashmir-vaishno-devi-with-kashmir-tour-6d5n','Vaishno Devi with Kashmir Tour','Kashmir','domestic',5,6,'₹ 17,499',NULL,NULL,'/images/packages/1785069204318-chatgpt-image-jul-26-2026-06-03-12-pm.png','[]','[\"Srinagar Sightseeing\", \"Shikara Ride\", \"Sonmarg Excursion\", \"Gulmarg Excursion\", \"Pahalgam Sightseeing\", \"Mata Vaishno Devi Darshan\"]','[]','[{\"day\": 1, \"title\": \"Jammu Arrival – Srinagar\", \"detail\": \"Arrive at Jammu Railway Station/Airport and proceed to Srinagar. Visit Mughal Gardens and enjoy a Shikara Ride on Dal Lake. Overnight stay in Srinagar.\"}, {\"day\": 2, \"title\": \"Sonmarg Excursion\", \"detail\": \"After breakfast, enjoy a full-day excursion to Sonmarg and return to Srinagar for overnight stay.\"}, {\"day\": 3, \"title\": \"Gulmarg Excursion\", \"detail\": \"Visit Gulmarg and enjoy its famous meadows, scenic landscapes, and optional Gondola Ride. Return to Srinagar.\"}, {\"day\": 4, \"title\": \"Pahalgam Sightseeing – Katra Transfer\", \"detail\": \"After breakfast, visit Betaab Valley, Aru Valley, and Chandanwari. Later proceed to Katra for overnight stay.\"}, {\"day\": 5, \"title\": \"Vaishno Devi Darshan\", \"detail\": \"Proceed for Mata Vaishno Devi Darshan. Return to Katra and relax after the pilgrimage.\"}, {\"day\": 6, \"title\": \"Jammu Departure\", \"detail\": \"After breakfast, transfer to Jammu Railway Station/Airport for your onward journey.\"}]',1,0,NULL,'Experience the perfect harmony of spirituality and natural beauty with our Vaishno Devi with Kashmir Tour, a memorable journey that combines one of India\'s most sacred pilgrimages with the breathtaking landscapes of Kashmir.\n\nBegin your adventure by exploring the scenic valleys of Srinagar, Sonmarg, Gulmarg, and Pahalgam, where snow-capped peaks, lush meadows, and the tranquil Dal Lake create unforgettable experiences. Complete your journey with the divine blessings of Mata Vaishno Devi, making this package an ideal blend of devotion, sightseeing, and peaceful relaxation.\n\nPerfect for families, pilgrims, and leisure travelers, this package offers comfortable accommodation, private transportation, and well-planned sightseeing for a meaningful and memorable North India holiday.',103,'2026-07-02 04:57:50.606','2026-08-03 14:38:54.915'),('0e151935-25b2-43f8-8ea6-e24b9cbf4718','himachal-spiti-valley-circuit-tour-9d8n','Spiti Valley Circuit Tour','Himachal Pradesh','domestic',8,9,'₹ 29,999',NULL,NULL,'/images/destinations/1785070446444-chatgpt-image-jul-26-2026-06-23-17-pm.png','[]','[\"Atal Tunnel\", \"Kaza\", \"Key Monastery\", \"Chandratal Lake\", \"Kibber Village\", \"Kunzum Pass\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Shimla\", \"detail\": \"Arrive in Shimla and relax before beginning your Spiti adventure.\"}, {\"day\": 2, \"title\": \"Shimla to Kalpa\", \"detail\": \"Drive through the scenic Kinnaur Valley to Kalpa.\"}, {\"day\": 3, \"title\": \"Kalpa to Kaza\", \"detail\": \"Travel via Nako, Tabo and Dhankar while enjoying spectacular mountain views.\"}, {\"day\": 4, \"title\": \"Kaza Sightseeing\", \"detail\": \"Visit Key Monastery, Kibber Village, Hikkim and Komic.\"}, {\"day\": 5, \"title\": \"Kaza Exploration\", \"detail\": \"Explore Langza Village and nearby attractions.\"}, {\"day\": 6, \"title\": \"Kaza to Chandratal\", \"detail\": \"Drive via Kunzum Pass and enjoy the beauty of Chandratal Lake.\"}, {\"day\": 7, \"title\": \"Chandratal to Manali\", \"detail\": \"Cross Atal Tunnel and arrive in Manali.\"}, {\"day\": 8, \"title\": \"Manali Sightseeing\", \"detail\": \"Visit Hadimba Temple, Mall Road and local attractions.\"}, {\"day\": 9, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey.\"}]',1,0,NULL,'Embark on the adventure of a lifetime with our Spiti Valley Circuit Tour, an extraordinary expedition through one of India\'s most spectacular high-altitude Himalayan destinations, renowned for its dramatic landscapes, ancient monasteries, and remote mountain villages.\n\nTravel across breathtaking mountain passes while exploring the charming towns of Kalpa and Kaza, the iconic Key Monastery, the world\'s highest inhabited villages including Hikkim, Komic, and Kibber, and the mesmerizing beauty of Chandratal Lake. Journey through the legendary Kunzum Pass and Atal Tunnel, where every turn reveals awe-inspiring views perfect for photography and adventure.\n\nDesigned for road trip enthusiasts, adventure seekers, and nature lovers, this package offers comfortable accommodation, private transportation, and carefully planned sightseeing, delivering an unforgettable experience through the untouched landscapes of Spiti Valley.',1105,'2026-07-02 04:57:50.606','2026-07-26 13:59:11.671'),('1121ec02-7cf6-49c9-ab6f-e475bcc60d51','madhya-pradesh-ujjain-omkareshwar-tour-package-4d3n','Ujjain & Omkareshwar Tour Package','Madhya Pradesh','domestic',3,4,'₹ 12,999',NULL,NULL,'/images/packages/1785079484881-chatgpt-image-jul-26-2026-08-54-32-pm.png','[]','[\"Mahakaleshwar Jyotirlinga\", \"Omkareshwar Jyotirlinga\", \"Mahakal Lok Corridor\", \"Kal Bhairav Temple\", \"Omkareshwar Temple &amp; Narmada River\", \"Comfortable Private Transportation\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Ujjain\", \"detail\": \"Arrive in Ujjain, visit Mahakaleshwar Temple, Mahakal Lok and Bade Ganeshji Ka Mandir before overnight stay.\"}, {\"day\": 2, \"title\": \"Ujjain Sightseeing\", \"detail\": \"Explore Kal Bhairav Temple, Harsiddhi Mata Temple, Mangalnath Temple, Ram Ghat and other major attractions.\"}, {\"day\": 3, \"title\": \"Omkareshwar Excursion\", \"detail\": \"Drive to Omkareshwar, seek blessings at Omkareshwar Jyotirlinga and Mamleshwar Temple before returning for overnight stay.\"}, {\"day\": 4, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey with divine memories.\"}]',1,0,NULL,'Experience a spiritually uplifting pilgrimage with our Ujjain & Omkareshwar Divine Jyotirlinga Tour, a sacred journey that brings together two of India\'s most revered Jyotirlingas in one unforgettable experience.\n\nBegin your pilgrimage in the holy city of Ujjain with darshan at the sacred Mahakaleshwar Jyotirlinga, followed by visits to the magnificent Mahakal Lok Corridor, Kal Bhairav Temple, Harsiddhi Mata Temple, and other renowned spiritual landmarks. Continue to the serene island town of Omkareshwar, where the sacred Omkareshwar Jyotirlinga and Mamleshwar Temple, set along the tranquil Narmada River, offer a truly divine atmosphere.\n\nIdeal for pilgrims, families, and devotees, this package combines comfortable accommodation, seamless transportation, and well-planned sightseeing for a spiritually fulfilling journey through Madhya Pradesh.',901,'2026-07-02 04:57:50.606','2026-07-26 15:24:48.828'),('13141cfe-0185-476d-a048-10315a8cb274','northeast-complete-north-east-grand-tour-featured-package-11d10n','Complete North East Grand Tour','North East India','domestic',10,11,'₹ 49,999',NULL,NULL,'/images/packages/1785232468079-chatgpt-image-jul-28-2026-03-24-16-pm.png','[]','[\"Kaziranga National Park\", \"Shillong &amp; Cherrapunji\", \"Dawki &amp; Umngot River\", \"Tawang Monastery\", \"Gangtok\", \"Tsomgo Lake\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Guwahati\", \"detail\": \"Explore Kamakhya Temple and the Brahmaputra Riverfront.\"}, {\"day\": 2, \"title\": \"Kaziranga National Park\", \"detail\": \"Enjoy a wildlife safari and tea garden visit.\"}, {\"day\": 3, \"title\": \"Shillong\", \"detail\": \"Travel to Shillong via Umiam Lake.\"}, {\"day\": 4, \"title\": \"Cherrapunji &amp; Dawki\", \"detail\": \"Visit waterfalls, caves and the crystal-clear Umngot River.\"}, {\"day\": 5, \"title\": \"Guwahati to Bomdila\", \"detail\": \"Enter Arunachal Pradesh and enjoy mountain landscapes.\"}, {\"day\": 6, \"title\": \"Bomdila to Tawang\", \"detail\": \"Cross Sela Pass and visit Jaswant Garh.\"}, {\"day\": 7, \"title\": \"Tawang Sightseeing\", \"detail\": \"Explore Tawang Monastery and Madhuri Lake.\"}, {\"day\": 8, \"title\": \"Fly/Transfer to Gangtok Region\", \"detail\": \"Travel towards Sikkim.\"}, {\"day\": 9, \"title\": \"Gangtok Sightseeing\", \"detail\": \"Visit Tsomgo Lake, Baba Mandir and MG Marg.\"}, {\"day\": 10, \"title\": \"Local Exploration\", \"detail\": \"Enjoy shopping and scenic viewpoints before departure preparations.\"}, {\"day\": 11, \"title\": \"Departure\", \"detail\": \"Transfer to Airport/Railway Station for your onward journey.\"}]',1,0,NULL,'Embark on the ultimate journey through the breathtaking landscapes of North East India with our Complete North East Grand Tour, a comprehensive holiday that beautifully combines wildlife, pristine rivers, majestic mountains, ancient monasteries, and vibrant local cultures across Assam, Meghalaya, Arunachal Pradesh, and Sikkim.\n\nSeek blessings at the sacred Kamakhya Temple, enjoy an exciting wildlife safari in Kaziranga National Park, explore the picturesque hill station of Shillong, and witness the crystal-clear waters of the Umngot River in Dawki. Continue your adventure through the spectacular Sela Pass to the magnificent Tawang Monastery before discovering the serene beauty of Gangtok, Tsomgo Lake, and Baba Mandir amidst the Eastern Himalayas.\n\nIdeal for families, couples, adventure seekers, and first-time visitors, this premium package offers comfortable accommodation, private transportation, and expertly planned sightseeing, making it the perfect way to experience the diverse beauty and rich culture of North East India.',802,'2026-07-02 04:57:50.606','2026-07-28 09:54:30.597'),('166575b0-43dc-43dc-adcd-ca5b7cea0d57','odisha-complete-odisha-explorer-premium-8d7n','Complete Odisha Explorer','Odisha','domestic',7,8,'₹ 31,999',NULL,NULL,'/images/packages/1785086605530-chatgpt-image-jul-26-2026-10-53-11-pm.png','[]','[\"Jagannath Temple\", \"Konark Sun Temple\", \"Chilika Lake Dolphin Cruise\", \"Puri Beach\", \"Gopalpur Beach\", \"Lingaraj Temple\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Bhubaneswar\", \"detail\": \"Arrive in Bhubaneswar and visit Lingaraj Temple, Mukteshwar Temple and Dhauli Shanti Stupa.\"}, {\"day\": 2, \"title\": \"Bhubaneswar to Puri\", \"detail\": \"Visit Jagannath Temple, Gundicha Temple and relax at Puri Beach.\"}, {\"day\": 3, \"title\": \"Konark &amp; Chandrabhaga\", \"detail\": \"Explore Konark Sun Temple, Chandrabhaga Beach and Raghurajpur Heritage Village.\"}, {\"day\": 4, \"title\": \"Chilika Lake Excursion\", \"detail\": \"Enjoy a dolphin cruise at Satapada and explore Chilika Lake.\"}, {\"day\": 5, \"title\": \"Puri to Gopalpur\", \"detail\": \"Drive to Gopalpur and spend the evening relaxing at Gopalpur Beach.\"}, {\"day\": 6, \"title\": \"Gopalpur Sightseeing\", \"detail\": \"Visit Taratarini Temple and enjoy leisure at the beach.\"}, {\"day\": 7, \"title\": \"Return to Bhubaneswar\", \"detail\": \"Explore Nandankanan Zoological Park and Ekamra Haat before overnight stay.\"}, {\"day\": 8, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey.\"}]',1,0,NULL,'Experience the very best of Odisha on this grand journey that brings together its spiritual heritage, scenic beauty, coastal charm, and rich culture.\n\nTravel through Bhubaneswar, Puri, Konark, Chilika, and Gopalpur, visiting iconic attractions like Jagannath Temple, Konark Sun Temple, and Chilika Lake. Enjoy dolphin cruises, relax on pristine beaches, and explore vibrant local culture.\n\nFrom sacred temples to serene coastlines, every moment of this tour is filled with discovery and unforgettable experiences.\n\nPerfect for families and explorers seeking a complete Odisha experience, this package offers premium stays, seamless transfers, and comprehensive sightseeing for a truly enriching journey.',2005,'2026-07-02 04:57:50.606','2026-07-26 17:23:30.914'),('17ee1289-d428-436c-abb4-b19478f4c87e','tamil-nadu-ooty-coonoor-madurai-heritage-escape-6d5n','Ooty – Coonoor – Madurai Heritage Escape','Tamil Nadu','domestic',5,6,'₹ 19,999',NULL,NULL,'/images/packages/1783014303395-ooty-coonoor-madurai-heritage-escape.png','[]','[\"Ooty Lake\", \"Doddabetta Peak\", \"Tea Gardens\", \"Dolphin\'s Nose\", \"Sim\'s Park\", \"Meenakshi Amman Temple\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Ooty\", \"detail\": \"Arrive in Ooty and relax at Ooty Lake while exploring the local market.\"}, {\"day\": 2, \"title\": \"Ooty Sightseeing\", \"detail\": \"Visit Doddabetta Peak, Botanical Garden, Rose Garden, Tea Museum and Tea Estates.\"}, {\"day\": 3, \"title\": \"Coonoor Excursion\", \"detail\": \"Explore Dolphin\'s Nose, Sim\'s Park, Lamb\'s Rock and scenic tea plantations.\"}, {\"day\": 4, \"title\": \"Ooty to Madurai\", \"detail\": \"Travel to Madurai and enjoy an evening exploring the local markets.\"}, {\"day\": 5, \"title\": \"Madurai Heritage Tour\", \"detail\": \"Visit Meenakshi Amman Temple, Thirumalai Nayakkar Palace and Gandhi Memorial Museum.\"}, {\"day\": 6, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey.\"}]',1,0,NULL,'Escape into the serene beauty of the Nilgiri Hills with our Ooty – Coonoor – Madurai tour, a perfect blend of lush landscapes and rich cultural heritage.\n\nDiscover the charm of Ooty with visits to Ooty Lake, Doddabetta Peak, botanical gardens, and sprawling tea estates, followed by scenic excursions to Coonoor’s Dolphin’s Nose and Sim’s Park.\n\nContinue your journey to Madurai, where ancient temples, vibrant markets, and historical landmarks offer a deep dive into Tamil Nadu’s cultural roots.\n\nPerfect for nature lovers and culture enthusiasts, this package combines relaxation, exploration, and comfortable travel for a refreshing holiday experience.',202,'2026-07-02 04:57:50.606','2026-07-27 16:01:51.126'),('1be1d05b-c499-4676-98e8-f3f207aba25e','andaman-complete-andaman-grand-tour-7d6n','Complete Andaman Grand Tour','Andaman Islands','domestic',6,7,'₹ 34,999',NULL,NULL,'/images/packages/1785071672727-chatgpt-image-jul-26-2026-06-44-21-pm.png','[]','[\"6 Nights Accommodation\", \"Daily Breakfast\", \"Airport Pickup &amp; Drop\", \"Private AC Vehicle for Sightseeing\", \"Inter-Island Ferry Tickets\", \"Complete Sightseeing as per Itinerary\", \"Toll Tax &amp; Parking Charges\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Port Blair\", \"detail\": \"Arrive in Port Blair and visit Cellular Jail, Corbyn\'s Cove Beach and the Light &amp; Sound Show.\"}, {\"day\": 2, \"title\": \"Port Blair to Havelock Island\", \"detail\": \"Transfer to Havelock Island and enjoy Radhanagar Beach.\"}, {\"day\": 3, \"title\": \"Havelock Adventure\", \"detail\": \"Visit Elephant Beach and enjoy scuba diving, snorkeling and water sports.\"}, {\"day\": 4, \"title\": \"Havelock to Neil Island\", \"detail\": \"Explore Bharatpur Beach, Natural Bridge and Laxmanpur Beach.\"}, {\"day\": 5, \"title\": \"Neil Island to Port Blair\", \"detail\": \"Return to Port Blair and enjoy leisure time and local shopping.\"}, {\"day\": 6, \"title\": \"Ross Island &amp; North Bay\", \"detail\": \"Visit Ross Island, North Bay Island and enjoy optional adventure activities.\"}, {\"day\": 7, \"title\": \"Departure\", \"detail\": \"After breakfast, transfer to Port Blair Airport for your onward journey.\"}]',1,0,NULL,'Experience the very best of the Andaman Islands with our Complete Andaman Grand Tour, an unforgettable tropical holiday that combines pristine beaches, vibrant marine life, historical landmarks, and exciting island adventures.\n\nExplore the historic charm of Port Blair, relax on the world-renowned Radhanagar Beach, and discover the natural beauty of Havelock Island (Swaraj Dweep) and Neil Island (Shaheed Dweep). Visit the fascinating Cellular Jail, Ross Island, and North Bay while enjoying optional scuba diving, snorkeling, and a variety of exciting water sports amidst crystal-clear waters and colorful coral reefs.\n\nIdeal for families, couples, honeymooners, and adventure seekers, this comprehensive package offers comfortable accommodation, private transportation, inter-island ferry transfers, and expertly planned sightseeing, making it the perfect way to experience the tropical paradise of the Andaman Islands.',1505,'2026-07-02 04:57:50.606','2026-07-26 13:14:38.395'),('1d2e1f65-ff4c-410c-8463-e8bc58b6abc0','maharashtra-lonavala-khandala-weekend-tour-3d2n','Lonavala – Khandala Weekend Tour','Maharashtra','domestic',2,3,'₹ 10,999',NULL,NULL,'/images/packages/1785080513322-chatgpt-image-jul-26-2026-09-11-39-pm.png','[]','[\"Tiger Point\", \"Bhushi Dam\", \"Karla Caves\", \"Rajmachi View Point\", \"Lion\'s Point\", \"Lonavala Market\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Lonavala\", \"detail\": \"Arrive in Lonavala, visit Bhushi Dam, Lion\'s Point and enjoy an evening at Lonavala Market.\"}, {\"day\": 2, \"title\": \"Lonavala Sightseeing\", \"detail\": \"Explore Tiger Point, Karla Caves and Rajmachi View Point before overnight stay.\"}, {\"day\": 3, \"title\": \"Departure\", \"detail\": \"After breakfast, proceed for your onward journey.\"}]',1,0,NULL,'Escape to the refreshing hills of the Western Ghats with our Lonavala – Khandala Hill Escape, a relaxing getaway featuring lush green valleys, cascading waterfalls, scenic viewpoints, and pleasant mountain weather.\n\nDiscover the natural beauty of Lonavala and Khandala as you visit Bhushi Dam, Tiger Point, Lion\'s Point, Rajmachi View Point, and Karla & Bhaja Caves. Enjoy panoramic valley views, explore charming local markets, and savor the famous Lonavala chikki while surrounded by mist-covered hills and tranquil landscapes.\n\nIdeal for couples, families, and weekend travelers, this package offers comfortable accommodation, private transportation, and carefully planned sightseeing for a rejuvenating holiday amidst nature.',1801,'2026-07-02 04:57:50.606','2026-07-26 15:41:57.656'),('1d3a3cd5-c558-4c8e-bb24-f1e9d31018f8','andaman-havelock-neil-island-explorer-5d4n','Havelock & Neil Island Explorer','Andaman Islands','domestic',4,5,'₹ 24,999',NULL,NULL,'/images/packages/1785071544509-chatgpt-image-jul-26-2026-06-42-09-pm.png','[]','[\"4 Nights Accommodation\", \"Daily Breakfast\", \"Airport Pickup &amp; Drop\", \"Private AC Vehicle for Sightseeing\", \"Inter-Island Ferry Tickets\", \"Complete Sightseeing as per Itinerary\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Port Blair\", \"detail\": \"Arrive in Port Blair and transfer to Havelock Island.\"}, {\"day\": 2, \"title\": \"Havelock Sightseeing\", \"detail\": \"Visit Radhanagar Beach and Elephant Beach with optional water sports.\"}, {\"day\": 3, \"title\": \"Neil Island Exploration\", \"detail\": \"Explore Bharatpur Beach, Natural Bridge and Laxmanpur Beach.\"}, {\"day\": 4, \"title\": \"Return to Port Blair\", \"detail\": \"Return by ferry and enjoy shopping and leisure time.\"}, {\"day\": 5, \"title\": \"Departure\", \"detail\": \"After breakfast, transfer to Port Blair Airport for your onward journey.\"}]',1,0,NULL,'Discover the breathtaking beauty of the Andaman archipelago with our Havelock & Neil Island Explorer, a relaxing island getaway featuring pristine beaches, turquoise waters, and unforgettable coastal landscapes.\n\nSpend your days exploring the world-famous Radhanagar Beach on Havelock Island (Swaraj Dweep), unwind at the picturesque Bharatpur Beach, admire the remarkable Natural Bridge, and witness spectacular sunsets at Laxmanpur Beach on Neil Island (Shaheed Dweep). Optional water sports, scenic ferry rides, and peaceful island surroundings make every moment of this journey truly memorable.\n\nPerfect for couples, honeymooners, and leisure travelers, this package combines comfortable accommodation, inter-island ferry transfers, private transportation, and carefully curated sightseeing for a refreshing tropical escape.',1504,'2026-07-02 04:57:50.606','2026-07-26 13:12:28.351'),('1d85a2d6-12e3-4f30-b506-f48fbc2bd495','tamil-nadu-madurai-rameswaram-kanyakumari-pilgrimage-tour-5d4n','Madurai – Rameswaram – Kanyakumari Pilgrimage Tour','Tamil Nadu','domestic',4,5,'₹ 15,999',NULL,NULL,'/images/packages/1785166094433-chatgpt-image-jul-27-2026-08-58-01-pm.png','[]','[\"Meenakshi Amman Temple\", \"Ramanathaswamy Temple\", \"Pamban Bridge\", \"Dhanushkodi\", \"Vivekananda Rock Memorial\", \"Thiruvalluvar Statue\"]','[]','[{\"day\": 1, \"title\": \"Arrival in Madurai\", \"detail\": \"Arrive in Madurai and visit Meenakshi Amman Temple, Thirumalai Nayakkar Palace and Gandhi Memorial Museum.\"}, {\"day\": 2, \"title\": \"Madurai to Rameswaram\", \"detail\": \"Cross the iconic Pamban Bridge and visit Ramanathaswamy Temple and Agni Theertham.\"}, {\"day\": 3, \"title\": \"Rameswaram Sightseeing\", \"detail\": \"Explore Dhanushkodi, Ram Setu View Point, Abdul Kalam Memorial and Kothandaramaswamy Temple.\"}, {\"day\": 4, \"title\": \"Kanyakumari Excursion\", \"detail\": \"Visit Vivekananda Rock Memorial, Thiruvalluvar Statue and enjoy the sunset at Kanyakumari.\"}, {\"day\": 5, \"title\": \"Departure\", \"detail\": \"After breakfast, witness the sunrise and proceed for your onward journey.\"}]',1,0,NULL,'Begin a soulful journey across Tamil Nadu with our Madurai – Rameswaram – Kanyakumari pilgrimage tour, where spirituality meets breathtaking coastal beauty.\n\nVisit revered landmarks including the magnificent Meenakshi Amman Temple in Madurai, the sacred Ramanathaswamy Temple in Rameswaram, and the iconic Pamban Bridge connecting the island.\n\nExperience the spiritual aura of Dhanushkodi and witness the magical sunrise and sunset at Kanyakumari, along with visits to Vivekananda Rock Memorial and Thiruvalluvar Statue.\n\nIdeal for families and spiritual seekers, this package ensures a peaceful and well-organized journey with comfortable accommodation, seamless travel, and meaningful experiences.',201,'2026-07-02 04:57:50.606','2026-07-27 15:28:17.255'),('1f5b71e6-e859-4177-ad44-29e42e322650','kashmir-kashmir-honeymoon-package-6d5n','Kashmir Honeymoon Escape','Kashmir','domestic',5,6,'₹ 27,999',NULL,NULL,'/images/packages/1785075526210-chatgpt-image-jul-26-202