INSERT INTO `services` VALUES ('056f07de-1b0d-4eeb-9b90-91aabe033310','hotels','Hotel Booking','Hand-picked hotels worldwide at exclusive rates.','From budget-friendly hotels to luxury resorts and boutique villas — we negotiate exclusive rates and free upgrades.','/images/services/1785238972925-chatgpt-image-jul-28-2026-05-12-37-pm.png','Hotel','[]','[]','[]','[]','{\"layout\": \"hotels\", \"features\": [{\"icon\": \"Hotel\", \"title\": \"3★ to 5★ hotels\", \"detail\": \"International chains and trusted local brands.\"}, {\"icon\": \"BedDouble\", \"title\": \"Resorts &amp; villas\", \"detail\": \"Beachfront, hillside and private pool villas.\"}, {\"icon\": \"Sparkles\", \"title\": \"Boutique stays\", \"detail\": \"Heritage havelis, ryokans and design hotels.\"}, {\"icon\": \"Star\", \"title\": \"Loyalty perks\", \"detail\": \"Free upgrades, early check-in &amp; late check-out where available.\"}], \"heroTitle\": \"Stays you\'ll remember\", \"catalogItems\": [{\"icon\": \"Hotel\", \"image\": \"/images/services/1785061164981-chatgpt-image-jul-26-2026-03-48-23-pm.png\", \"title\": \"Delhi\", \"detail\": \"\"}, {\"icon\": \"Hotel\", \"image\": \"/images/services/1785061299000-chatgpt-image-jul-26-2026-03-51-23-pm.png\", \"title\": \"Mumbai\", \"detail\": \"\"}, {\"icon\": \"Hotel\", \"image\": \"/images/services/1785061397172-chatgpt-image-jul-26-2026-03-52-58-pm.png\", \"title\": \"Bangalore\", \"detail\": \"\"}, {\"icon\": \"Hotel\", \"image\": \"/images/services/1785061528140-chatgpt-image-jul-26-2026-03-55-15-pm.png\", \"title\": \"Singapore\", \"detail\": \"\"}, {\"icon\": \"Hotel\", \"image\": \"/images/services/1785061644840-chatgpt-image-jul-26-2026-03-56-56-pm.png\", \"title\": \"Dubai\", \"detail\": \"\"}, {\"icon\": \"Hotel\", \"image\": \"/images/services/1785061815549-chatgpt-image-jul-26-2026-03-59-59-pm.png\", \"title\": \"New York\", \"detail\": \"\"}], \"sectionTitle\": \"Curated stays for every traveller\", \"heroBannerUrl\": \"/images/services/1785238972925-chatgpt-image-jul-28-2026-05-12-37-pm.png\"}',1,2,'Hotel Booking — Domestic &amp; International | YatraNexus',NULL,'2026-06-26 21:32:25.493','2026-07-28 11:42:55.375'),('434852f7-dd83-48df-b95f-ef1684355652','insurance','Travel Insurance','Stay covered for medical, baggage &amp; trip risks.','Comprehensive travel insurance for medical emergencies, trip cancellation, baggage loss and adventure activities — domestic and international.','/images/services/1785235823057-chatgpt-image-jul-28-2026-04-20-11-pm.png','ShieldCheck','[]','[]','[]','[]','{\"layout\": \"insurance\", \"features\": [{\"icon\": \"ShieldCheck\", \"title\": \"Medical emergencies\", \"detail\": \"Hospitalisation and evacuation cover abroad.\"}, {\"icon\": \"Plane\", \"title\": \"Trip cancellation\", \"detail\": \"Refund non-refundable costs if plans change.\"}, {\"icon\": \"Briefcase\", \"title\": \"Baggage protection\", \"detail\": \"Lost, delayed or damaged luggage cover.\"}, {\"icon\": \"Sparkles\", \"title\": \"Adventure add-ons\", \"detail\": \"Trekking, scuba and sports coverage available.\"}], \"heroTitle\": \"Travel with peace of mind\", \"sectionTitle\": \"Coverage that travels with you\", \"heroBannerUrl\": \"/images/services/1785235823057-chatgpt-image-jul-28-2026-04-20-11-pm.png\"}',1,5,'Travel Insurance | YatraNexus',NULL,'2026-06-26 21:32:25.493','2026-07-28 10:50:25.286'),('53a8a17d-6eaa-4d89-8e4c-49dbe79fb12e','corporate','Corporate Travel','Business tours &amp; MICE solutions for companies.','Business travel made simple with dedicated support, GST invoicing &amp; negotiated corporate fares.','/images/corporate/1785235233610-chatgpt-image-jul-28-2026-04-10-18-pm.png','Briefcase','[]','[]','[]','[]','{\"layout\": \"corporate\", \"features\": [{\"icon\": \"Plane\", \"title\": \"Business Travel\", \"detail\": \"Flights, hotels and ground transport under one desk.\"}, {\"icon\": \"Users\", \"title\": \"MICE &amp; Events\", \"detail\": \"Conferences, dealer meets and incentive trips.\"}, {\"icon\": \"Briefcase\", \"title\": \"Crew &amp; Bulk Bookings\", \"detail\": \"Group fares and block bookings for teams.\"}, {\"icon\": \"FileText\", \"title\": \"GST Billing\", \"detail\": \"Compliant invoicing and expense documentation.\"}, {\"icon\": \"Stamp\", \"title\": \"Visa, Insurance &amp; Forex\", \"detail\": \"Complete travel desk for international business.\"}, {\"icon\": \"Headphones\", \"title\": \"Dedicated Account Manager\", \"detail\": \"Single point of contact for all travel needs.\"}], \"titleFirst\": \"Corporate &amp; MICE\", \"heroBullets\": [\"End-to-end corporate travel management\", \"GST invoicing &amp; monthly MIS reports\", \"Dedicated account manager\", \"24×7 support on WhatsApp &amp; call\"], \"titleAccent\": \"Travel Solutions\", \"sectionTitle\": \"Our Corporate Services\", \"heroBannerUrl\": \"/images/corporate/1785235233610-chatgpt-image-jul-28-2026-04-10-18-pm.png\", \"detailedServices\": [{\"icon\": \"Briefcase\", \"image\": \"/images/services/1784898978973-chatgpt-image-jul-24-2026-06-45-58-pm.png\", \"title\": \"Corporate Travel Management\", \"accent\": \"purple\", \"detail\": \"End-to-end management of business trips — flights, hotels, cabs and approvals handled by your dedicated desk.\"}, {\"icon\": \"Users\", \"image\": \"/images/services/1784898847461-chatgpt-image-jul-24-2026-06-43-20-pm.png\", \"title\": \"Meetings &amp; Conferences (MICE)\", \"accent\": \"orange\", \"detail\": \"Venue selection, group bookings, transfers and on-ground coordination for conferences and events.\"}, {\"icon\": \"Plane\", \"image\": \"/images/services/1784899145307-chatgpt-image-jul-24-2026-06-48-08-pm.png\", \"title\": \"Crew &amp; Group Travel Solutions\", \"accent\": \"blue\", \"detail\": \"Block bookings, series fares and consolidated billing for teams, crew rotations and large groups.\"}, {\"icon\": \"MapPin\", \"image\": \"/images/services/1784900262796-37b41e7b-e590-482f-8783-8b730503edc6.png\", \"title\": \"Dealer Meets &amp; Exhibitions\", \"accent\": \"green\", \"detail\": \"Logistics for dealer meets, trade shows and exhibitions — travel, stay and local transport bundled.\"}], \"detailedSectionTitle\": \"Our Corporate Services\"}',1,8,'Corporate &amp; MICE Travel — YatraNexus','Business travel, MICE, crew bookings, GST invoicing and dedicated account management for companies.','2026-07-04 04:34:09.478','2026-07-28 10:40:36.501'),('694926da-3e1a-4acc-bed3-57b8dca5e6a5','flights','Flight Booking','Best fares on domestic &amp; international flights.','Domestic and international flights with airline-direct rates, complimentary seat selection advice, and real human support throughout your journey.','/images/services/1785238837616-chatgpt-image-jul-28-2026-05-10-25-pm.png','Plane','[]','[]','[]','[]','{\"layout\": \"flights\", \"features\": [{\"icon\": \"BadgePercent\", \"title\": \"Competitive fares\", \"detail\": \"Compared across 30+ airlines and consolidators.\"}, {\"icon\": \"Globe2\", \"title\": \"International routing\", \"detail\": \"Multi-city, codeshare and complex stopovers handled.\"}, {\"icon\": \"Plane\", \"title\": \"Cabin upgrades\", \"detail\": \"Business &amp; premium economy at the best available rates.\"}, {\"icon\": \"Headphones\", \"title\": \"24×7 reschedule help\", \"detail\": \"Cancellations, refunds and reschedules — we handle it.\"}], \"heroTitle\": \"Best fares, smarter routes\", \"catalogItems\": [{\"icon\": \"Plane\", \"image\": \"/images/services/1785061164981-chatgpt-image-jul-26-2026-03-48-23-pm.png\", \"title\": \"Delhi\", \"detail\": \"\"}, {\"icon\": \"Plane\", \"image\": \"/images/services/1785061299000-chatgpt-image-jul-26-2026-03-51-23-pm.png\", \"title\": \"Mumbai\", \"detail\": \"\"}, {\"icon\": \"Plane\", \"image\": \"/images/services/1785061397172-chatgpt-image-jul-26-2026-03-52-58-pm.png\", \"title\": \"Bangalore\", \"detail\": \"\"}, {\"icon\": \"Plane\", \"image\": \"/images/services/1785061528140-chatgpt-image-jul-26-2026-03-55-15-pm.png\", \"title\": \"Singapore\", \"detail\": \"\"}, {\"icon\": \"Plane\", \"image\": \"/images/services/1785061644840-chatgpt-image-jul-26-2026-03-56-56-pm.png\", \"title\": \"Dubai\", \"detail\": \"\"}, {\"icon\": \"Hotel\", \"image\": \"/images/services/1785061815549-chatgpt-image-jul-26-2026-03-59-59-pm.png\", \"title\": \"New york\", \"detail\": \"\"}], \"sectionTitle\": \"Why book flights with us\", \"heroBannerUrl\": \"/images/services/1785238837616-chatgpt-image-jul-28-2026-05-10-25-pm.png\"}',1,1,'Flight Booking — Domestic &amp; International | YatraNexus',NULL,'2026-06-26 21:32:25.493','2026-07-28 11:40:40.622'),('9b32d8fc-aa51-4a34-9842-baeb1eca9e8e','packages','Holiday Packages','Curated holidays across India and abroad.','Hand-crafted itineraries across India — fully customisable with real experts on WhatsApp.','/images/services/1785240805317-chatgpt-image-jul-28-2026-05-43-12-pm.png','Palmtree','[]','[]','[]','[]','{\"layout\": \"holiday\", \"eyebrow\": \"Holiday packages\", \"titleFirst\": \"Holidays you\'ll\", \"titleAccent\": \"Remember\", \"sectionTitle\": \"Browse by region\", \"heroBannerUrl\": \"/images/services/1785240805317-chatgpt-image-jul-28-2026-05-43-12-pm.png\"}',1,4,'Holiday Packages — Domestic &amp; International | YatraNexus','Curated holiday packages across India — Goa, Kerala, Rajasthan, Kashmir and more.','2026-07-03 08:38:26.547','2026-07-28 12:13:28.287'),('a786526c-db7a-4c7c-a216-50be8acbccf5','forex','Forex Card','Multi-currency forex cards at competitive rates.','Multi-currency forex cards and cash at competitive rates — load once, spend worldwide with better rates than airport counters.','/images/services/1785236101817-chatgpt-image-jul-28-2026-04-24-49-pm.png','CreditCard','[]','[]','[]','[]','{\"layout\": \"forex\", \"features\": [{\"icon\": \"CreditCard\", \"title\": \"Multi-currency cards\", \"detail\": \"Load USD, EUR, GBP, AED and more.\"}, {\"icon\": \"Wallet\", \"title\": \"Competitive rates\", \"detail\": \"Better than airport counters and most banks.\"}, {\"icon\": \"ShieldCheck\", \"title\": \"Secure &amp; insured\", \"detail\": \"Chip-and-PIN cards with emergency replacement.\"}, {\"icon\": \"Globe2\", \"title\": \"Cash + card combo\", \"detail\": \"Mix of forex card and currency notes delivered.\"}], \"heroTitle\": \"Spend smarter abroad\", \"catalogItems\": [{\"icon\": \"CreditCard\", \"image\": \"/images/services/1785062877459-chatgpt-image-jul-26-2026-04-17-37-pm.png\", \"title\": \"Single Currency Forex Card\", \"accent\": \"purple\", \"detail\": \"Perfect for travelers visiting a single destination.\", \"points\": [\"Load one foreign currency\", \"Lock exchange rates before travel\", \"Secure Chip &amp; PIN protection\", \"Accepted worldwide at merchants &amp; ATMs\", \"Easy reload when required\"]}, {\"icon\": \"Globe2\", \"image\": \"/images/services/1785063021922-chatgpt-image-jul-26-2026-04-20-04-pm.png\", \"title\": \"Multi Currency Forex Card\", \"accent\": \"pink\", \"detail\": \"One card for multiple international destinations.\", \"points\": [\"Load multiple currencies on one card\", \"Seamless currency switching\", \"No need to carry multiple cards\", \"Worldwide merchant &amp; ATM acceptance\", \"Convenient online reload facility\"]}, {\"icon\": \"GraduationCap\", \"image\": \"/images/services/1785063228151-chatgpt-image-jul-26-2026-04-23-31-pm.png\", \"title\": \"Student Forex Card\", \"accent\": \"orange\", \"detail\": \"Specially designed for students studying abroad.\", \"points\": [\"Ideal for tuition &amp; living expenses\", \"Parents can easily reload funds\", \"Worldwide ATM &amp; merchant access\", \"Secure Chip &amp; PIN protection\", \"Competitive exchange rates\"]}, {\"icon\": \"Briefcase\", \"image\": \"/images/services/1785063371165-chatgpt-image-jul-26-2026-04-25-54-pm.png\", \"title\": \"Corporate Forex Card\", \"accent\": \"blue\", \"detail\": \"Smart travel solution for business professionals.\", \"points\": [\"Manage international business expenses\", \"Accepted globally for travel &amp; payments\", \"Easy expense tracking &amp; control\", \"Convenient reload &amp; fund management\", \"Secure transactions with Chip &amp; PIN\"]}], \"sectionTitle\": \"Forex made simple\", \"heroBannerUrl\": \"/images/services/1785236101817-chatgpt-image-jul-28-2026-04-24-49-pm.png\"}',1,6,'Forex Card — Multi-currency Travel Money | YatraNexus',NULL,'2026-06-26 21:32:25.493','2026-07-28 10:55:06.086'),('a9c1126e-e284-4f60-935f-55e6288480cd','visa','Visa Services','End-to-end visa assistance for 100+ countries.','End-to-end visa assistance for tourist and business travel — document prep, appointments and tracking across popular destinations.','/images/services/1785239377582-chatgpt-image-jul-28-2026-05-19-20-pm.png','Stamp','[]','[]','[]','[]','{\"steps\": [{\"n\": 1, \"title\": \"Free consultation\", \"detail\": \"Share your destination, travel dates and visa type with our expert.\"}, {\"n\": 2, \"title\": \"Document checklist\", \"detail\": \"We review your documents and guide you on anything missing.\"}, {\"n\": 3, \"title\": \"Application filing\", \"detail\": \"Forms completed and embassy or VFS appointment booked for you.\"}, {\"n\": 4, \"title\": \"Tracking &amp; updates\", \"detail\": \"Real-time status updates until your visa is approved.\"}, {\"n\": 5, \"title\": \"Travel ready\", \"detail\": \"Collect your visa and depart with complete peace of mind.\"}], \"layout\": \"visa\", \"ctaTitle\": \"Planning your international trip?\", \"heroTitle\": \"Visa Made Simple\", \"ctaSubtitle\": \"Let our visa experts help you get your visa approved with ease.\", \"sectionTitle\": \"Tourist and business visa types with indicative processing timelines for Indian passport holders.\", \"heroBannerUrl\": \"/images/services/1785239377582-chatgpt-image-jul-28-2026-05-19-20-pm.png\", \"visaCountries\": [{\"type\": \"\", \"country\": \"Australia\", \"processing\": \"\", \"touristType\": \"Visitor Visa (Subclass 600)\", \"businessType\": \"Business Visitor Stream (Subclass 600)\", \"processingNote\": \"Tourist: 15–30 days; Business: 15–30 days (Some applications may take longer)\"}, {\"type\": \"\", \"country\": \"Canada\", \"processing\": \"\", \"touristType\": \"Temporary Resident Visa (TRV)\", \"businessType\": \"Business Visitor\", \"processingNote\": \"Tourist: 3–8 weeks; Business: 3–8 weeks (Varies by biometrics &amp; IRCC workload)\"}, {\"type\": \"\", \"country\": \"Dubai / UAE\", \"processing\": \"\", \"touristType\": \"30/60-Day Tourist Visa\", \"businessType\": \"Business Visit Visa\", \"processingNote\": \"Tourist: 2–5 working days (Express: 24–48 hours); Business: 3–5 working days\"}, {\"type\": \"\", \"country\": \"Schengen Countries (Europe)\", \"processing\": \"\", \"touristType\": \"Short-Stay (Type C)\", \"businessType\": \"Business Schengen Visa\", \"processingNote\": \"Tourist: 15–30 calendar days; Business: 15–30 calendar days (Apply 30–45 days before travel)\"}, {\"type\": \"\", \"country\": \"Indonesia (Bali)\", \"processing\": \"\", \"touristType\": \"Tourist Visa / Visa on Arrival\", \"businessType\": \"Business Visa\", \"processingNote\": \"Tourist: Instant (VOA) / 3–5 working days (eVisa); Business: 5–10 working days\"}, {\"type\": \"\", \"country\": \"Japan\", \"processing\": \"\", \"touristType\": \"Short-Term Tourist\", \"businessType\": \"Temporary Business Visitor\", \"processingNote\": \"Tourist: 5–7 working days; Business: 5–7 working days\"}, {\"type\": \"\", \"country\": \"Malaysia\", \"processing\": \"\", \"touristType\": \"Tourist eVisa\", \"businessType\": \"Business Visa\", \"processingNote\": \"Tourist: 2–5 working days; Business: 3–5 working days\"}, {\"type\": \"\", \"country\": \"Maldives\", \"processing\": \"\", \"touristType\": \"Visa on Arrival\", \"businessType\": \"Business Visa\", \"processingNote\": \"Tourist: Visa on Arrival; Business: 5–10 working days\"}, {\"type\": \"\", \"country\": \"New Zealand\", \"processing\": \"\", \"touristType\": \"Visitor Visa\", \"businessType\": \"Business Visitor Visa\", \"processingNote\": \"Tourist: 20–30 working days; Business: 20–30 working days\"}, {\"type\": \"\", \"country\": \"Saudi Arabia\", \"processing\": \"\", \"touristType\": \"Tourist eVisa\", \"businessType\": \"Business Visit Visa\", \"processingNote\": \"Tourist: 1–3 working days; Business: 3–7 working days\"}, {\"type\": \"\", \"country\": \"Singapore\", \"processing\": \"\", \"touristType\": \"Tourist eVisa\", \"businessType\": \"Business Visit Visa\", \"processingNote\": \"Tourist: 3–5 working days; Business: 3–5 working days\"}, {\"type\": \"\", \"country\": \"South Africa\", \"processing\": \"\", \"touristType\": \"Visitor Visa\", \"businessType\": \"Business Visa\", \"processingNote\": \"Tourist: 5–10 working days; Business: 5–10 working days\"}, {\"type\": \"\", \"country\": \"South Korea\", \"processing\": \"\", \"touristType\": \"Tourist Visa\", \"businessType\": \"Business Visa\", \"processingNote\": \"Tourist: 7–15 working days; Business: 7–15 working days\"}, {\"type\": \"\", \"country\": \"Thailand\", \"processing\": \"\", \"touristType\": \"Tourist Visa / eVOA\", \"businessType\": \"Non-Immigrant B (Business)\", \"processingNote\": \"Tourist: 3–7 working days; Business: 5–10 working days\"}, {\"type\": \"\", \"country\": \"Turkey\", \"processing\": \"\", \"touristType\": \"eVisa\", \"businessType\": \"Business eVisa / Sticker Visa\", \"processingNote\": \"Tourist eVisa: Within 24 hours; Business: 5–15 working days\"}, {\"type\": \"\", \"country\": \"United Kingdom\", \"processing\": \"\", \"touristType\": \"Standard Visitor\", \"businessType\": \"Standard Visitor (Business Activities)\", \"processingNote\": \"Tourist: 15 working days (Priority: 5 days); Business: 15 working days (Priority &amp; Super Priority available)\"}, {\"type\": \"\", \"country\": \"United States\", \"processing\": \"\", \"touristType\": \"B1/B2 Visitor\", \"businessType\": \"B1 Business\", \"processingNote\": \"Tourist: Visa approval 3–10 working days after interview. Interview appointment may take a few days to several months. Business: Same timeline.\"}, {\"type\": \"\", \"country\": \"Vietnam\", \"processing\": \"\", \"touristType\": \"Tourist eVisa\", \"businessType\": \"Business Visa\", \"processingNote\": \"Tourist: 3–5 working days; Business: 5–7 working days\"}], \"ctaButtonLabel\": \"Send Visa Inquiry\"}',1,4,'Visa Services — Tourist &amp; Business Visa Assistance | YatraNexus',NULL,'2026-06-26 21:32:25.493','2026-07-28 11:49:40.444'),('e2df8823-2c3f-4ff2-9e1e-781517c39875','cabs','Outstation Cabs','Comfortable cabs for intercity travel across India.','Comfortable, well-maintained cabs for intercity travel across India — sedan, SUV and tempo traveller options with experienced drivers.','/images/services/1785239079400-chatgpt-image-jul-28-2026-05-14-23-pm.png','Car','[]','[]','[]','[]','{\"layout\": \"cabs\", \"features\": [{\"icon\": \"Car\", \"title\": \"Sedan, SUV &amp; tempo\", \"detail\": \"Right vehicle for couples, families and groups.\"}, {\"icon\": \"MapPin\", \"title\": \"Pan-India coverage\", \"detail\": \"One-way and round-trip outstation routes.\"}, {\"icon\": \"ShieldCheck\", \"title\": \"Verified drivers\", \"detail\": \"Experienced, courteous and GPS-tracked.\"}, {\"icon\": \"Clock\", \"title\": \"Flexible timings\", \"detail\": \"Early morning pickups and multi-day circuits.\"}], \"heroTitle\": \"Comfortable cabs, anywhere in India\", \"catalogItems\": [{\"icon\": \"Car\", \"image\": \"/images/services/1785060229923-chatgpt-image-jul-26-2026-03-13-10-pm.png\", \"title\": \"Sedan\", \"detail\": \"4 Seater · 2 Bags\\nDzire, Etios, Aura- Ideal for couples and small famalies.\"}, {\"icon\": \"Car\", \"image\": \"/images/services/1785238506069-chatgpt-image-jul-28-2026-05-04-50-pm.png\", \"title\": \"SUV\", \"detail\": \"6 Seater · 4 Bags\\nEartiga, XL6- comfertable for hilly routes and 5-6 travellers.\"}, {\"icon\": \"Car\", \"image\": \"/images/services/1785060505126-chatgpt-image-jul-26-2026-03-28-23-pm.png\", \"title\": \"Innova/Crysta\", \"detail\": \"6-7 Seater · 6 Bags\\nPremium SUV for families and longer journeys.\"}, {\"icon\": \"Car\", \"image\": \"/images/services/1785060116931-chatgpt-image-jul-26-2026-03-31-32-pm.png\", \"title\": \"Tampo Traveller\", \"detail\": \"11-15 Seater · 7+ Bags\\nPerfect for groups, weddings and corporate outings.\"}], \"sectionTitle\": \"Why book cabs with us\", \"heroBannerUrl\": \"/images/services/1785239079400-chatgpt-image-jul-28-2026-05-14-23-pm.png\"}',1,3,'Outstation Cabs — Intercity Travel | YatraNexus',NULL,'2026-06-26 21:32:25.493','2026-07-28 11:44:42.453');
