INSERT INTO `site_settings` VALUES (1,'+91 99250 10377','919925010377','info@yatranexus.com','919925010377','L/8, Gokul Complex, Opp. Gurukul Temple, Drive-In Road, Gurukul, Ahmedabad- 380052',NULL,'Mon–Sat, 9:00 AM – 7:00 PM IST','{\"facebook\": \"https://www.facebook.com/share/1DgWv639rJ/\", \"linkedin\": \"https://www.linkedin.com/company/yatranexus/\", \"instagram\": \"https://www.instagram.com/yatranexus?igsh=N2tkcjlrdnppbGFo\"}','YatraNexus Ventures LLP. We craft thoughtful journeys across India and the world.',NULL,NULL,'YatraNexus Ventures LLP','Your Journey, Our Priority','{\"faq\": {\"eyebrow\": \"FAQs\", \"subtitle\": \"Quick answers about booking, payments, visas and support.\", \"titleFirst\": \"Questions,\", \"titleAccent\": \"answered\"}, \"blog\": {\"eyebrow\": \"Blog\", \"subtitle\": \"Ideas and advice for your next trip across India and beyond.\", \"titleFirst\": \"Stories, tips\", \"titleAccent\": \"&amp; guides\"}, \"site\": {\"seoTitle\": \"YatraNexus — Flights, Hotels, Holidays, Visa &amp; Cabs\", \"seoDescription\": \"YatraNexus Ventures LLP — flights, hotels, holiday packages, cabs, visa, travel insurance and forex. Your Journey, Our Priority.\", \"whatsappPreset\": \"Hi YatraNexus, I\'d like to plan a trip.\", \"showInternational\": false, \"commonPackageExclusions\": [\"Flights / airfare\", \"Travel insurance\", \"Visa fees\", \"Personal expenses &amp; tips\", \"Optional activities &amp; excursions\", \"Early check-in / late check-out\"], \"corporateWhatsappMessage\": \"Hi YatraNexus corporate desk, we\'d like to discuss business travel for our company.\"}, \"about\": {\"eyebrow\": \"About YatraNexus\", \"ctaTitle\": \"Ready to plan with us?\", \"subtitle\": \"We believe travel should be simple, stress-free and memorable. From flights and hotels to holidays, visa and corporate travel — YatraNexus is your trusted partner at every step.\", \"bannerUrl\": \"https://fgrsjqkboltbwatfhcnm.supabase.co/storage/v1/object/public/cms-images/banners/1785236301331-chatgpt-image-jul-28-2026-04-28-08-pm.png\", \"offerItems\": [{\"icon\": \"Plane\", \"title\": \"Flight Assistance\", \"accent\": \"purple\", \"detail\": \"Domestic &amp; international fares with expert support.\"}, {\"icon\": \"Building2\", \"title\": \"Hotel Reservations\", \"accent\": \"orange\", \"detail\": \"Hand-picked stays at negotiated rates.\"}, {\"icon\": \"Palmtree\", \"title\": \"Holiday Packages\", \"accent\": \"blue\", \"detail\": \"Curated itineraries across India &amp; abroad.\"}, {\"icon\": \"Car\", \"title\": \"Cabs &amp; Airport Transfers\", \"accent\": \"green\", \"detail\": \"Reliable ground transport when you land.\"}, {\"icon\": \"Stamp\", \"title\": \"Visa Assistance\", \"accent\": \"purple\", \"detail\": \"Documentation and processing for 100+ countries.\"}, {\"icon\": \"ShieldCheck\", \"title\": \"Travel Insurance\", \"accent\": \"orange\", \"detail\": \"Coverage for medical, baggage &amp; trip risks.\"}, {\"icon\": \"CreditCard\", \"title\": \"Forex Card &amp; Currency\", \"accent\": \"blue\", \"detail\": \"Multi-currency cards at competitive rates.\"}, {\"icon\": \"Briefcase\", \"title\": \"Corporate &amp; MICE Travel\", \"accent\": \"green\", \"detail\": \"Business travel desk with GST billing &amp; MIS.\"}], \"offerTitle\": \"What We Offer\", \"titleFirst\": \"Your Journey.\", \"ctaSubtitle\": \"Tell us where you want to go — our experts will handle the rest.\", \"titleAccent\": \"Our Priority.\", \"valuesItems\": [{\"icon\": \"Handshake\", \"title\": \"Trust\", \"detail\": \"\"}, {\"icon\": \"Shield\", \"title\": \"Transparency\", \"detail\": \"\"}, {\"icon\": \"Star\", \"title\": \"Customer Satisfaction\", \"detail\": \"\"}, {\"icon\": \"ShieldCheck\", \"title\": \"Reliability\", \"detail\": \"\"}, {\"icon\": \"UserCircle\", \"title\": \"Professionalism\", \"detail\": \"\"}, {\"icon\": \"TrendingUp\", \"title\": \"Continuous Improvement\", \"detail\": \"\"}], \"valuesTitle\": \"Our Values\", \"visionTitle\": \"Our Vision\", \"missionTitle\": \"Our Mission\", \"visionDetail\": \"To become India\'s most trusted travel partner — known for service, transparency and journeys that travellers recommend to friends and family.\", \"whoWeAreBody\": \"YatraNexus is a new-age travel startup built around one simple idea — every traveller deserves a real expert, not a chatbot.\\n\\nWhether you\'re booking a family holiday, a business trip or a group tour, our team handles the details so you can focus on the experience.\\n\\nFrom the first call to your return home, we\'re with you on WhatsApp and phone — transparent pricing, honest advice and support when you need it most.\", \"missionDetail\": \"To make travel planning easy, affordable and reliable for every Indian traveller — with human experts and honest pricing at the core.\", \"whoWeAreTitle\": \"Who We Are\"}, \"terms\": {\"body\": \"By using the YatraNexus website and services, you agree to receive travel quotes and communications related to your inquiry.\\n\\nBookings are subject to airline, hotel and supplier terms. Prices and availability can change until confirmed.\\n\\nCancellation and refund policies depend on the specific booking and will be shared before you confirm payment.\", \"title\": \"Terms &amp; Conditions\"}, \"contact\": {\"eyebrow\": \"Contact us\", \"ctaTitle\": \"Prefer WhatsApp?\", \"formNote\": \"We respond on WhatsApp &amp; call within working hours.\", \"promises\": [{\"icon\": \"Zap\", \"title\": \"Same-Day Callback\", \"detail\": \"Share your inquiry and hear back from a travel expert within working hours.\"}, {\"icon\": \"MessageCircle\", \"title\": \"WhatsApp Support\", \"detail\": \"Quick answers on chat — ideal for dates, fares and itinerary tweaks.\"}, {\"icon\": \"Headphones\", \"title\": \"Dedicated Experts\", \"detail\": \"Real humans who know flights, hotels, visa and holidays — not bots.\"}], \"subtitle\": \"Call, email or WhatsApp — our travel desk responds quickly during business hours.\", \"bannerUrl\": \"https://fgrsjqkboltbwatfhcnm.supabase.co/storage/v1/object/public/cms-images/banners/1785236881346-chatgpt-image-jul-28-2026-04-37-42-pm.png\", \"formTitle\": \"Send an inquiry\", \"titleFirst\": \"Let\'s plan your\", \"ctaSubtitle\": \"Message our team for the fastest response.\", \"titleAccent\": \"next trip\", \"formSubtitle\": \"Share your plan and we\'ll get back within working hours.\", \"promisesTitle\": \"Why contact us\"}, \"gallery\": {\"eyebrow\": \"Gallery\", \"subtitle\": \"A glimpse of destinations and experiences we love planning.\", \"titleFirst\": \"Moments from\", \"titleAccent\": \"the journey\"}, \"privacy\": {\"body\": \"We respect your privacy. Information you share through inquiry forms is used only to respond to your travel requests and improve our services.\\n\\nWe do not sell your personal data. Contact details may be shared with trusted travel partners only as needed to fulfil your booking.\\n\\nFor privacy questions, email us at the address listed on our Contact page.\", \"title\": \"Privacy Policy\"}, \"homepage\": {\"trustBar\": [{\"icon\": \"BadgeCheck\", \"title\": \"Best Prices Guaranteed\", \"detail\": \"\"}, {\"icon\": \"Headphones\", \"title\": \"24/7 Customer Support\", \"detail\": \"\"}, {\"icon\": \"Shield\", \"title\": \"Secure Payments 100% Safe\", \"detail\": \"\"}, {\"icon\": \"Sparkles\", \"title\": \"Hassle-Free Experience\", \"detail\": \"\"}], \"trustPills\": [\"Domestic &amp; International Travel\", \"Personalized Planning\", \"Trusted Travel Partners\", \"Dedicated Customer Support\"], \"domesticTitle\": \"Domestic Destinations\", \"featuredTitle\": \"Featured Holiday Plans\", \"tourTypesLead\": \"Browse by the kind of trip you\'re dreaming about — adventure, family, honeymoon and more.\", \"whyChooseLead\": \"YatraNexus is built around one promise - every traveller deserves a real expert, not a chatbot. From a weekend Goa break to a multi-country honeymoon, we plan, book and stay with you end-to-end.\", \"howItWorksLead\": \"From a quick WhatsApp hello to a fully booked trip – here\'s how easy it is.\", \"tourTypesTitle\": \"Tour Type Packages\", \"whyChooseTitle\": \"Travel with people who actually pick up the phone.\", \"domesticEyebrow\": \"Incredible India\", \"featuredEyebrow\": \"Bestsellers\", \"howItWorksTitle\": \"How It Works\", \"testimonialsLead\": \"Real stories from real trips planned by our team.\", \"tourTypesEyebrow\": \"Hand-picked for you\", \"whyChooseEyebrow\": \"Why choose us\", \"destinationPrices\": {}, \"howItWorksEyebrow\": \"3 Simple Steps\", \"testimonialsTitle\": \"Happy Customers\", \"corporateBannerUrl\": \"https://fgrsjqkboltbwatfhcnm.supabase.co/storage/v1/object/public/cms-images/corporate/1783164235452-contact-hero.png\", \"destinationTaglines\": {}, \"testimonialsEyebrow\": \"Loved by travellers\"}, \"navigation\": {\"bottomLinks\": [{\"to\": \"/privacy-policy\", \"label\": \"Privacy Policy\"}, {\"to\": \"/terms\", \"label\": \"Terms\"}, {\"to\": \"/terms\", \"label\": \"Cancellation Policy\"}, {\"to\": \"/privacy-policy\", \"label\": \"Cookies\"}], \"headerLinks\": [{\"to\": \"/\", \"label\": \"Home\"}, {\"to\": \"/corporate\", \"label\": \"Corporate Travel\"}, {\"to\": \"/about\", \"label\": \"About Us\"}, {\"to\": \"/contact\", \"label\": \"Contact Us\"}], \"companyLinks\": [{\"to\": \"/about\", \"label\": \"About Us\"}, {\"to\": \"/contact\", \"label\": \"Contact\"}, {\"to\": \"/blog\", \"label\": \"Blog\"}], \"exploreLinks\": [{\"to\": \"/services\", \"label\": \"All services\"}, {\"to\": \"/corporate\", \"label\": \"Corporate Travel\"}, {\"to\": \"/services/cabs\", \"label\": \"Outstation Cabs\"}, {\"to\": \"/services/flights\", \"label\": \"Flight Booking\"}, {\"to\": \"/services/hotels\", \"label\": \"Hotel Booking\"}, {\"to\": \"/holiday-packages\", \"label\": \"Holiday Packages\"}, {\"to\": \"/services/visa\", \"label\": \"Visa Services\"}, {\"to\": \"/services/insurance\", \"label\": \"Travel Insurance\"}, {\"to\": \"/services/forex\", \"label\": \"Forex Card\"}]}, \"testimonials\": {\"eyebrow\": \"Testimonials\", \"subtitle\": \"Real feedback from guests who travelled with YatraNexus.\", \"titleFirst\": \"Loved by\", \"titleAccent\": \"travellers\"}, \"servicesIndex\": {\"eyebrow\": \"Our services\", \"subtitle\": \"From a single flight to a full honeymoon itinerary — pick a service below and our team will handle the rest on WhatsApp or phone.\", \"bannerUrl\": \"https://fgrsjqkboltbwatfhcnm.supabase.co/storage/v1/object/public/cms-images/banners/1785237126506-chatgpt-image-jul-28-2026-04-41-55-pm.png\", \"titleFirst\": \"Everything you need\", \"titleAccent\": \"to travel\"}, \"holidayDomestic\": {\"eyebrow\": \"Incredible India\", \"subtitle\": \"Pick a state to view highlights, sample packages and request a quote.\", \"bannerUrl\": \"/images/hero/holiday-packages-hero-desktop.png\", \"titleFirst\": \"Explore India\", \"titleAccent\": \"by State\"}, \"holidayInternational\": {\"eyebrow\": \"Beyond borders\", \"subtitle\": \"Pick a destination to view highlights, sample packages and request a quote.\", \"bannerUrl\": \"/images/hero/holiday-packages-hero-desktop.png\", \"titleFirst\": \"Explore the\", \"titleAccent\": \"World\"}}','2026-08-06 14:47:10.204');
