INSERT INTO `testimonials` VALUES ('041ee7e6-67f4-431a-922e-e33cace37550','Nirmit Vaghela','Bhavnagar',NULL,'Very happy with the services — quick response and the best price.',4,NULL,1,5,'2026-06-26 21:32:25.493'),('2bf71dbf-99f2-4444-95ec-0f661d5f1911','Jatin Trivedi','Ahmedabad',NULL,'YatraNexus planned our Rajasthan trip beautifully. Their travel expert was on WhatsApp through the entire trip.',5,'/images/hero/holiday-packages-hero-desktop.webp',1,1,'2026-06-26 21:32:25.493'),('93c7c1ba-2f5c-4599-bbab-81681adb7cb0','Pravin Kumar Dabhi','Neemuch',NULL,'Our Himachal Pradesh trip was a fantastic experience.',5,NULL,1,4,'2026-06-26 21:32:25.493'),('d9bfac97-c6b8-49a2-aa17-8be6f01ede3a','Ketuman Kashyap','Udaipur',NULL,'Wonderful Kashmir trip - everything was well planned.',4,'/images/testimonials/1783052464133-kerala-family-holiday.png',1,2,'2026-06-26 21:32:25.493'),('f07676ff-53d9-411d-ac90-d993a91f9ee2','Chirag Dohre','Ahmedabad',NULL,'YatraNexus planned our Maharastra Jyotirlinga trip beautifully. ',3,NULL,1,3,'2026-06-29 13:53:19.353');
